def backfill_enrolled_on(apps, schema_editor):
    """Existing students were on the register from their creation (or earliest attendance),
    not from the day of this upgrade, so past reports must not call them unenrolled."""
    from django.db.models import Min
    from django.utils import timezone

    Student = apps.get_model("app1", "Student")
    Attendance = apps.get_model("app1", "Attendance")
    earliest = dict(
        Attendance.objects.values("student_id").annotate(first=Min("date")).values_list("student_id", "first")
    )
    for student in Student.objects.all().only("pk", "created_at"):
        candidates = [timezone.localtime(student.created_at).date()]
        if student.pk in earliest:
            candidates.append(earliest[student.pk])
        Student.objects.filter(pk=student.pk).update(enrolled_on=min(candidates))


